contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, bool doTransfer) public payable {
        require(newOwner != address(0));
        address before = c.owner();
        bool reverted;
        if (doTransfer) {
            try c.transferOwnership(newOwner) { reverted = false; } catch { reverted = true; }
            if (!reverted) {
                assert(c.owner() == newOwner);
            } else {
                assert(c.owner() == before);
            }
        } else {
            assert(c.owner() == before);
        }
    }
    receive() external payable {}
}

